#pragma once
#include "Hero.h"
#include <windows.h>
struct PlayerCommand{Vec2 move,mouseWorldPosition;bool basic=false,clickBasic=false,ultimate=false,toggleAim=false,togglePause=false,start=false,restart=false;UpgradeChoice upgrade=UpgradeChoice::None;};
class InputManager{public:PlayerCommand Read(HWND window);PlayerCommand ReadAttackEdges(bool click,bool keyK,bool keyJ,bool tab);void ResetEdges();static Vec2 MouseWorldPosition(POINT cursor,RECT client){return client.right>0&&client.bottom>0?Vec2{1280.0F*cursor.x/client.right,720.0F*cursor.y/client.bottom}:Vec2{};}static Vec2 MoveVector(bool left,bool right,bool up,bool down){return Normalize({static_cast<float>(right-left),static_cast<float>(down-up)});}static bool BasicCommand(bool leftMouse,bool keyK){return leftMouse||keyK;}private:bool previousClick_=false,previousK_=false,previousUltimate_=false,previousTab_=false,previousPause_=false,previousEnter_=false,previousRestart_=false,previous1_=false,previous2_=false,previous3_=false;};
